#!/usr/bin/env python3
"""Read-only Liberty (.lib) timing extractor.

A Liberty file is a nested, brace-delimited structure whose table attributes
(index_1, values, ...) are quoted strings folded over many physical lines with
a trailing backslash. Truncating a cell at the next `cell(`, or counting braces
that appear inside a string, therefore corrupts the result, so this parser is
deliberately lexical:

  * block comments and quoted strings (escape aware) are single tokens, so a
    `{`, `}` or `;` inside a string can never desynchronise nesting;
  * backslash + newline continuations are folded before tokenizing, which is
    what makes a multi-line values(...) table one attribute;
  * an explicit stack of enclosing block names attributes every value to its
    own scope, so a nested pin/timing/cell_rise block is never mistaken for a
    cell-level property;
  * the source file is only ever opened for reading.
"""
from __future__ import annotations

import argparse
import collections
import csv
import os
import re
import sys

TOKEN = re.compile(
    r'/\*.*?\*/'                                     # block comment
    r'|"(?:[^"\\\n]|\\.)*"'                          # quoted string, escape aware
    r'|[A-Za-z_][A-Za-z0-9_]*'                       # attribute / block keyword
    r'|[{}();:,]'                                    # syntax punctuation
    r'|-?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?'    # bare number
    r'|\S',                                          # any other single character
    re.DOTALL,
)

NUMBER = re.compile(r'-?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?')
IDENT = re.compile(r'[A-Za-z_][A-Za-z0-9_]*\Z')

LIBRARY_METRICS = ["time_unit", "voltage_unit", "current_unit", "pullup_voltage",
                   "nom_voltage", "nom_temperature", "nom_process"]


def read_source(path):
    """Slurp the library read-only and fold physical line continuations."""
    with open(path, "r", encoding="utf-8", errors="replace") as handle:
        text = handle.read()
    return text.replace("\\\n", "")


class Lexer:
    """Token stream with one-token pushback, exposing raw character spans."""

    def __init__(self, text):
        self.text = text
        self._matches = TOKEN.finditer(text)
        self._pending = collections.deque()

    def peek(self):
        if not self._pending:
            found = next(self._matches, None)
            if found is not None:
                self._pending.append(found)
        return self._pending[0] if self._pending else None

    def take(self):
        if self._pending:
            return self._pending.popleft()
        return next(self._matches, None)

    def span(self, start, end_match):
        return self.text[start:end_match.start()] if end_match else self.text[start:]


class LibertyParser:
    def __init__(self, wanted):
        self.wanted = set(wanted)
        self.library = None
        self.meta = {}
        self.cell_count = 0
        self.timing_total = 0
        self.cells = {}
        self.stack = []
        self.cur_cell = None
        self.rise_depth = 0

    def in_cell(self):
        return self.stack[:2] == ["library", "cell"] and self.cur_cell is not None

    def record(self):
        return self.cells.get(self.cur_cell)

    def open_block(self, name, arg):
        if name == "library" and not self.stack:
            self.library = arg
        elif name == "cell" and self.stack == ["library"]:
            self.cell_count += 1
            self.cur_cell = arg
            if arg in self.wanted:
                self.cells[arg] = {"area": "", "inputs": 0, "outputs": 0,
                                   "timing": 0, "rise_tables": 0, "max_rise": None}
        elif name == "timing":
            self.timing_total += 1
            if self.in_cell():
                rec = self.record()
                if rec is not None:
                    rec["timing"] += 1
        if name == "cell_rise":
            self.rise_depth += 1
            if self.in_cell():
                rec = self.record()
                if rec is not None:
                    rec["rise_tables"] += 1
        self.stack.append(name)

    def table_attribute(self, name, raw):
        if name != "values" or not self.rise_depth or not self.in_cell():
            return
        rec = self.record()
        if rec is None:
            return
        numbers = [float(value) for value in NUMBER.findall(raw)]
        if numbers:
            best = max(numbers)
            rec["max_rise"] = best if rec["max_rise"] is None else max(rec["max_rise"], best)

    def scalar_attribute(self, name, raw):
        value = raw.strip()
        if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
            value = value[1:-1]
        if self.stack == ["library"]:
            if name in LIBRARY_METRICS:
                self.meta[name] = value
        elif self.stack == ["library", "cell"] and name == "area":
            rec = self.record()
            if rec is not None:
                rec["area"] = value
        elif (name == "direction" and self.in_cell() and len(self.stack) == 3
              and self.stack[2] == "pin"):
            rec = self.record()
            if rec is not None:
                if value == "input":
                    rec["inputs"] += 1
                elif value == "output":
                    rec["outputs"] += 1

    def run(self, text):
        lex = Lexer(text)
        while True:
            token = lex.take()
            if token is None:
                break
            word = token.group()
            if word.startswith("/*"):
                continue
            if word == "}":
                if self.stack:
                    closed = self.stack.pop()
                    if closed == "cell_rise":
                        self.rise_depth -= 1
                    if closed == "cell":
                        self.cur_cell = None
                continue
            if not IDENT.match(word):
                continue
            nxt = lex.peek()
            following = nxt.group() if nxt else ""
            if following == "(":
                lparen = lex.take()                           # consume '('
                raw = self.consume_arguments(lex, lparen.end())
                after = lex.peek()
                tail = after.group() if after else ""
                if tail == "{":
                    lex.take()
                    self.open_block(word, raw.strip().strip('"'))
                else:
                    if tail == ";":
                        lex.take()
                    self.table_attribute(word, raw)
                continue
            if following == ":":
                colon = lex.take()
                raw = self.consume_until_semicolon(lex, colon.end())
                self.scalar_attribute(word, raw)
                continue
            if following == "{":                              # bare `name {`
                lex.take()
                self.open_block(word, "")
                continue

    @staticmethod
    def consume_arguments(lex, start):
        """Consume through the matching ')'; return the raw argument text."""
        depth = 1
        while True:
            token = lex.take()
            if token is None:
                return lex.span(start, None)
            word = token.group()
            if word == "(":
                depth += 1
            elif word == ")":
                depth -= 1
                if depth == 0:
                    return lex.span(start, token)

    @staticmethod
    def consume_until_semicolon(lex, start):
        while True:
            token = lex.take()
            if token is None:
                return lex.span(start, None)
            if token.group() == ";":
                return lex.span(start, token)


def write_outputs(out_dir, parser, cells):
    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "library.csv"), "w", newline="",
              encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["metric", "value"])
        writer.writerow(["library", parser.library or ""])
        writer.writerow(["time_unit", parser.meta.get("time_unit", "")])
        writer.writerow(["nom_voltage", parser.meta.get("nom_voltage", "")])
        writer.writerow(["nom_temperature", parser.meta.get("nom_temperature", "")])
        writer.writerow(["cell_count", str(parser.cell_count)])
        writer.writerow(["timing_group_count", str(parser.timing_total)])

    with open(os.path.join(out_dir, "cells.csv"), "w", newline="",
              encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["cell", "area", "input_pin_count", "output_pin_count",
                         "timing_group_count", "cell_rise_table_count", "max_cell_rise"])
        for name in sorted(set(cells)):
            rec = parser.cells.get(name)
            if rec is None:
                continue
            max_rise = "" if rec["max_rise"] is None else "%.6f" % rec["max_rise"]
            writer.writerow([name, rec["area"], str(rec["inputs"]), str(rec["outputs"]),
                             str(rec["timing"]), str(rec["rise_tables"]), max_rise])


def main(argv=None):
    ap = argparse.ArgumentParser(description="bounded, read-only Liberty extractor")
    ap.add_argument("--lib", required=True, help="path to the source .lib (read only)")
    ap.add_argument("--cells", required=True, help="comma separated cell names")
    ap.add_argument("--out-dir", default="out", help="directory for the result CSVs")
    args = ap.parse_args(argv)

    wanted = [name.strip() for name in args.cells.split(",") if name.strip()]
    parser = LibertyParser(wanted)
    parser.run(read_source(args.lib))
    write_outputs(args.out_dir, parser, wanted)

    found = sorted(parser.cells)
    print("cells requested=%d parsed=%d missing=%s"
          % (len(set(wanted)), len(found),
             ",".join(sorted(set(wanted) - set(found))) or "-"))
    print("library=%s cells=%d timing_groups=%d time_unit=%s nom_voltage=%s"
          % (parser.library, parser.cell_count, parser.timing_total,
             parser.meta.get("time_unit"), parser.meta.get("nom_voltage")))
    for name in found:
        rec = parser.cells[name]
        print("  %s area=%s in=%d out=%d tg=%d rise=%d max_rise=%s"
              % (name, rec["area"], rec["inputs"], rec["outputs"], rec["timing"],
                 rec["rise_tables"],
                 "" if rec["max_rise"] is None else "%.6f" % rec["max_rise"]))
    return 0


if __name__ == "__main__":
    sys.exit(main())
